    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def get_pos(obj):
        if not isinstance(obj, dict):
            return None
        for k in ("position", "pos", "loc", "location", "coord", "coords", "xy"):
            p = obj.get(k)
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return [p[0], p[1]]
        x = obj.get("x")
        y = obj.get("y")
        if isinstance(x, (int, float)) and isinstance(y, (int, float)):
            return [x, y]
        return None

    def own_pos(obs):
        if not isinstance(obs, dict):
            return [0, 0]
        for k in ("self", "agent", "player", "me"):
            p = get_pos(obs.get(k))
            if p is not None:
                return p
        for k in ("agent_position", "player_position", "self_position", "my_position", "position"):
            p = obs.get(k)
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return [p[0], p[1]]
        if isinstance(obs.get("x"), (int, float)) and isinstance(obs.get("y"), (int, float)):
            return [obs.get("x"), obs.get("y")]
        return [0, 0]

    def iter_points(v):
        if v is None:
            return
        if isinstance(v, dict):
            p = get_pos(v)
            if p is not None:
                yield p
                return
            for vv in v.values():
                for p in iter_points(vv):
