    def nearest(points, me):
        best = None
        best_d = None
        for p in points:
            dx = p[0] - me[0]
            dy = p[1] - me[1]
            d = dx * dx + dy * dy
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best, best_d

