        if dx == 0 and dy == 0:
            score -= 0.2

        # Small directional tiebreak: prioritize cardinal over diagonal for stability.
        if dx != 0 and dy != 0:
            score -= 0.01

        if best_score is None or score > best_score:
            best_score = score
            best_move = [clamp(dx), clamp(dy)]

    return best_move

